        {
            this.WarehouseUnitId = METInventLocation::getWarehouseUnit(inventTransferLine.itemId, inventTransferLine.inventDim());

            //CS - CB715_TransferOrderExtract - PS
            /*this.TOUnitWeight = METWHSPhysDimUOMSite::convertWeight(
                                inventTransferLine.itemId, 1, inventTransferLine.UnitId, inventTransferLine.inventDim());
            this.TOUnitVolume = METWHSPhysDimUOMSite::convertVolume(
                                inventTransferLine.itemId, 1,  inventTransferLine.UnitId, inventTransferLine.inventDim());*/
            
            this.TOUnitWeight = METWHSPhysDimUOMSite::convertWeight(
                                inventTransferLine.itemId, 1, this.WarehouseUnitId, inventTransferLine.inventDim());
            this.TOUnitVolume = METWHSPhysDimUOMSite::convertVolume(
                                inventTransferLine.itemId, 1,  this.WarehouseUnitId, inventTransferLine.inventDim());
            //CE - CB715_TransferOrderExtract - PS
        }
    }

/// <summary>
/// Update unit weight, unit volume, unit case
/// </summary>
public void updateUnitFields()
{
    if (this.RecId)
    {
        ttsbegin;
        this.selectForUpdate(true);
        this.setUnitFields();
        this.setCaseQtyFields();
        this.update();
        ttscommit;
    }
}

    /// <summary>
    /// Set case quantity fields
    /// </summary>
    public void setCaseQtyFields()
    {
        InventTransferLine      inventTransferLine = this.InventTransferLine();
        UnitOfMeasureFromRecId  fromUnit,toUnit;        
        Factor                  factor;
        UnitOfMeasureSymbol     unitInvent          = InventTableModule::find(inventTransferLine.itemId, ModuleInventPurchSales::Invent).UnitId;

        if (inventTransferLine.itemId && inventTransferLine.UnitId && this.WarehouseUnitId)
        {   
            toUnit              = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventTransferLine.UnitId);
            fromUnit            = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.WarehouseUnitId);

            factor              = EcoResProductUnitConverter::convertForReleasedProduct(
                                    inventTransferLine.ItemId,
                                    inventTransferLine.inventDimId,
                                    1,
                                    fromUnit,
                                    toUnit,
                                    NoYes::No,
                                    NoYes::No);

            if(factor)
            {
                this.Cases          = real2int(inventTransferLine.QtyTransfer / factor);
                this.BrokenCase     = real2int(inventTransferLine.QtyTransfer - (this.Cases * factor));

                if(this.TOUnitWeight)
                {
                    this.TotalWeight    = (inventTransferLine.QtyTransfer / factor) * this.TOUnitWeight;
                }
                if(this.TOUnitVolume)
                {
                    this.TotalVolume    = (inventTransferLine.QtyTransfer / factor) * this.TOUnitVolume;
                }
            }

            // CB715_TransferOrderExtract
            // new field ShipCaseQty to save unit conversion factor and expose it in METWMSTransferOrderTransEntity
            this.ShipCaseQty = factor;

            this.ActualUnitCase = roundUp(UnitOfMeasureConversion::findByConversion(
                                UnitOfMeasure::findBySymbol(unitInvent).RecId,
                                UnitOfMeasure::findBySymbol(METConstants::unitcase).RecId,
                                EcoResProduct::findByProductNumber(inventTransferLine.ItemId).RecId).Factor, 0);
            this.ActualUnitVolume = METWHSPhysDimUOMSite::convertVolume(inventTransferLine.ItemId, this.TotalVolume, unitInvent, inventTransferLine.inventDim());
            this.ActualUnitWeight = METWHSPhysDimUOMSite::convertWeight(inventTransferLine.ItemId, this.TotalWeight, unitInvent, inventTransferLine.inventDim());
            this.ActualBrokenCase = this.metActualBrokenCase();
            /*this.Cases          =   UnitOfMeasureConverter::convert(inventTransferLine.QtyTransfer,
                                    fromUnit,toUnit,
                                    NoYes::No,
                                    InventTable::itemProduct(inventTransferLine.itemId),
                                    NoYes::No);*/

            //uomConversion       = UnitOfMeasureConversion::findByConversion(fromUnit,toUnit,InventTable::find(inventTransferLine.ItemId).Product);

            //this.BrokenCase     = inventTransferLine.QtyTransfer - (this.Cases * uomConversion.Factor);

        }
    }

    /// <summary>
    /// Returns Actual broken cases
    /// </summary>
    /// <returns>Actual broken cases</returns>
    public METBrokenCase metActualBrokenCase()
    {
        //Show broken case for each line that equals to the ordered quantity for sell units that are in "ea".
        //For any other sell units broken case=0
        //return this.SalesUnit == METConstants::unitEach ? this.SalesQty : 0;

        InventTransferLine      inventTransferLine  = this.InventTransferLine();
        UnitOfMeasureSymbol     unitInvent          = InventTableModule::find(inventTransferLine.itemId, ModuleInventPurchSales::Invent).UnitId;
        UnitOfMeasureSymbol     fromUnit            = this.WarehouseUnitId;
        METInventTransView      views;

        select sum(Qty) from views where views.ReferenceId == inventTransferLine.TransferId
                && views.inventTransId == inventTransferLine.InventTransId
                && views.StatusIssue == StatusIssue::ReservPhysical;
        inventqty  reservedQty = (abs(views.Qty));

        Factor factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        inventTransferLine.ItemId,
                        inventTransferLine.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(unitInvent),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(fromUnit),
                        NoYes::No,
                        NoYes::No);


        METCase actualCase = any2Int(fromUnit == METConstants::unitEach ? 0 : (factor * reservedQty));
        
        return real2int(reservedQty-(actualCase*(1/factor)));

    }

/// <summary>
/// Find sales line record using the invent trans Id and return.
/// </summary>
/// <returns>
/// <t>SalesLine</t> table buffer
/// </returns>
public SalesLine salesLine_InventTransId(boolean _forUpdate = false)
{
    return SalesLine::findInventTransId(this.SalesLineTransId, _forUpdate);
}

/// <summary>
/// Check if a transfer order line exists for a given invent trans id
/// </summary>
/// <param name = "_inventTransId">Sales line inventTransId</param>
/// <returns>true if record exists, otherwise false</returns>
public static boolean existsForSalesLine(InventTransId _inventTransId)
{
    InventTransferLine transferLine;
    
    select firstonly RecId from transferLine
        where transferLine.InventTransIdReceive == _inventTransId;
    
    return transferLine.RecId != 0;
}
